WITH base AS (SELECT id, country, city, rating, TRIM(country) AS clean_country, COALESCE(city, 'N/A') AS resolved_city FROM suppliers WHERE city IS NOT NULL AND city IN ('Tokyo', 'London', 'New York')), metrics AS (SELECT id, country, city, clean_country, resolved_city, NTILE(4) OVER (PARTITION BY city ORDER BY rating, id) AS rating_bucket, ROW_NUMBER() OVER (PARTITION BY country, city ORDER BY rating, id) AS event_seq FROM base), with_windows AS (SELECT *, LEAD(event_seq) OVER (PARTITION BY city ORDER BY rating_bucket, id) AS next_event_seq, LAG(rating_bucket) OVER (PARTITION BY city ORDER BY rating_bucket, id) AS prev_rating_bucket, LEAD(rating_bucket) OVER (PARTITION BY city ORDER BY rating_bucket, id) AS next_rating_bucket, ROW_NUMBER() OVER (PARTITION BY city ORDER BY rating_bucket, id) AS row_seq, SUM(rating_bucket) OVER (PARTITION BY country ORDER BY event_seq, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_rating_bucket FROM metrics), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY city, country ORDER BY row_seq NULLS FIRST, id) AS rn FROM with_windows) x WHERE rn = 1), base_suppliers AS (SELECT id, country, city, clean_country, resolved_city, rating_bucket, event_seq, next_event_seq, prev_rating_bucket, next_rating_bucket, row_seq, cumulative_rating_bucket, rn, ROUND(next_rating_bucket, 0) AS next_rating_bucket_rounded, ROUND(row_seq / cumulative_rating_bucket, 2) AS row_seq_per_cumulative_rating_bucket, COALESCE(city, 'UNKNOWN') AS resolved_city_2 FROM latest WHERE next_event_seq >= 5) SELECT country, PERCENTILE_APPROX(cumulative_rating_bucket, 0.95) AS cumulative_rating_bucket_p95, COUNT(CASE WHEN city = 'Chiang Mai' THEN 1 END) AS chiang_mai_count, PERCENTILE_APPROX(prev_rating_bucket, ARRAY(0.25, 0.5, 0.75)) AS prev_rating_bucket_quartiles FROM base_suppliers GROUP BY 1 ORDER BY chiang_mai_count DESC;
